// 작업 타임라인 컴포넌트 - 캘린더형 (Week/Month/Year)
// 일정은 주(row) 단위 오버레이에서 grid-column span으로 렌더링
import { useState, useMemo, useCallback } from 'react';
import type { Project, ProjectTask, ProjectTodo } from '../../types/work';
import type { ScheduleEvent } from '../../types';
import { getHolidayName } from '../../utils/holidays';
import { useSwipe } from '../../hooks/useSwipe';
import './WorkTimeline.css';

// ===== 타입 정의 =====
type ZoomLevel = 'week' | 'month' | 'year';

interface DisplayItem {
  id: string;
  title: string;
  color: string;
  startAt: Date | null;
  endAt: Date | null;
  isAllDay: boolean;
  original: Project | ProjectTask | ProjectTodo | ScheduleEvent;
  type: 'project' | 'task' | 'todo' | 'schedule';
  isScheduleEvent?: boolean;
}

// 주 단위 세그먼트
interface WeekSegment {
  item: DisplayItem;
  colStart: number;  // 1-7
  colEnd: number;    // 2-8 (exclusive)
  isStart: boolean;  // 이벤트의 시작인지
  isEnd: boolean;    // 이벤트의 끝인지
  lane: number;      // 겹침 처리용 레인
}

// ===== 유틸리티 함수 =====

function parseDate(dateStr: string | null): Date | null {
  if (!dateStr) return null;
  return new Date(dateStr);
}

// 주의 시작일 (월요일)
function getWeekStart(date: Date): Date {
  const d = new Date(date);
  const day = d.getDay();
  const diff = d.getDate() - day + (day === 0 ? -6 : 1);
  d.setDate(diff);
  d.setHours(0, 0, 0, 0);
  return d;
}

// 주의 마지막일 (일요일)
function getWeekEnd(date: Date): Date {
  const start = getWeekStart(date);
  const end = new Date(start);
  end.setDate(end.getDate() + 6);
  end.setHours(23, 59, 59, 999);
  return end;
}

// 두 날짜 중 큰 값
function maxDate(d1: Date, d2: Date): Date {
  return d1 > d2 ? d1 : d2;
}

// 두 날짜 중 작은 값
function minDate(d1: Date, d2: Date): Date {
  return d1 < d2 ? d1 : d2;
}

// 같은 날짜인지 비교
function isSameDay(d1: Date, d2: Date): boolean {
  return d1.getFullYear() === d2.getFullYear() &&
         d1.getMonth() === d2.getMonth() &&
         d1.getDate() === d2.getDate();
}

// 날짜를 YYYY-MM-DD 형식으로 변환
function formatDateStr(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

// 날짜 차이 (일 단위)
function daysBetween(start: Date, end: Date): number {
  const s = new Date(start);
  s.setHours(0, 0, 0, 0);
  const e = new Date(end);
  e.setHours(0, 0, 0, 0);
  return Math.round((e.getTime() - s.getTime()) / (1000 * 60 * 60 * 24));
}

// weekStart 기준 날짜의 인덱스 (0-6)
function dayIndex(date: Date, weekStart: Date): number {
  return daysBetween(weekStart, date);
}

// 이벤트를 주 단위 세그먼트로 분할
function splitToWeekSegment(
  item: DisplayItem,
  weekStart: Date
): WeekSegment | null {
  if (!item.startAt || !item.endAt) return null;
  
  const weekEnd = getWeekEnd(weekStart);
  
  // 이벤트가 이 주와 겹치는지 확인
  if (item.endAt < weekStart || item.startAt > weekEnd) return null;
  
  const segStart = maxDate(item.startAt, weekStart);
  const segEnd = minDate(item.endAt, weekEnd);
  
  const colStart = dayIndex(segStart, weekStart) + 1; // 1-7
  const colEnd = dayIndex(segEnd, weekStart) + 2;     // grid-end는 exclusive
  
  return {
    item,
    colStart: Math.max(1, Math.min(7, colStart)),
    colEnd: Math.max(2, Math.min(8, colEnd)),
    isStart: isSameDay(segStart, item.startAt),
    isEnd: isSameDay(segEnd, item.endAt),
    lane: 1,
  };
}

// 겹침 처리 - 레인 배치
function assignLanes(segments: WeekSegment[]): WeekSegment[] {
  if (segments.length === 0) return [];
  
  // 시작 컬럼 순으로 정렬
  const sorted = [...segments].sort((a, b) => a.colStart - b.colStart);
  
  // 각 레인의 마지막 끝 컬럼 추적
  const laneEnds: number[] = [];
  
  return sorted.map(seg => {
    // 사용 가능한 레인 찾기
    let lane = 1;
    for (let i = 0; i < laneEnds.length; i++) {
      if (laneEnds[i] <= seg.colStart) {
        lane = i + 1;
        laneEnds[i] = seg.colEnd;
        return { ...seg, lane };
      }
    }
    // 새 레인 필요
    lane = laneEnds.length + 1;
    laneEnds.push(seg.colEnd);
    return { ...seg, lane };
  });
}

// ===== Props 타입 =====

// ===== WeekRow 컴포넌트 =====
function WeekRow({
  weekStart,
  items,
  showDayNumbers = true,
  isCurrentMonth,
  onItemClick,
  onDateClick,
}: {
  weekStart: Date;
  items: DisplayItem[];
  showDayNumbers?: boolean;
  isCurrentMonth?: (date: Date) => boolean;
  onItemClick: (item: DisplayItem) => void;
  onDateClick?: (date: Date) => void;
}) {
  // 주의 날짜들
  const days = useMemo(() => {
    const result: Date[] = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(weekStart);
      d.setDate(d.getDate() + i);
      result.push(d);
    }
    return result;
  }, [weekStart]);
  
  // 세그먼트 생성 및 레인 배치
  const segments = useMemo(() => {
    const segs: WeekSegment[] = [];
    
    items.forEach(item => {
      const seg = splitToWeekSegment(item, weekStart);
      if (seg) segs.push(seg);
    });
    
    return assignLanes(segs);
  }, [items, weekStart]);
  
  const today = new Date();
  const maxLanes = Math.max(1, ...segments.map(s => s.lane));
  
  return (
    <div className="week-row" style={{ '--max-lanes': maxLanes } as React.CSSProperties}>
      {/* 날짜 셀 그리드 (배경) */}
      <div className="day-cells-grid">
        {days.map((day, idx) => {
          const isToday = isSameDay(day, today);
          const inMonth = isCurrentMonth ? isCurrentMonth(day) : true;
          const dateStr = formatDateStr(day);
          const holidayName = getHolidayName(dateStr);
          
          return (
            <div
              key={idx}
              className={`day-cell ${isToday ? 'today' : ''} ${!inMonth ? 'other-month' : ''} ${holidayName ? 'holiday' : ''}`}
              onClick={() => onDateClick?.(day)}
            >
              {showDayNumbers && (
                <div className="day-number-row">
                  <span className={`day-number ${isToday ? 'today' : ''} ${holidayName ? 'holiday' : ''}`}>
                    {day.getDate()}
                  </span>
                  {holidayName && <span className="holiday-name">{holidayName}</span>}
                </div>
              )}
            </div>
          );
        })}
      </div>
      
      {/* 이벤트 오버레이 */}
      <div className="events-overlay">
        {segments.map((seg, idx) => (
          <div
            key={`${seg.item.id}-${idx}`}
            className={`event-bar ${seg.isStart ? 'start' : ''} ${seg.isEnd ? 'end' : ''} ${seg.item.isScheduleEvent ? 'schedule-event' : ''}`}
            style={{
              '--col-start': seg.colStart,
              '--col-end': seg.colEnd,
              '--lane': seg.lane,
              '--item-color': seg.item.color,
            } as React.CSSProperties}
            onClick={(e) => {
              e.stopPropagation();
              onItemClick(seg.item);
            }}
            title={seg.item.title}
          >
            <span className="event-title">{seg.item.title}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ===== Week 뷰 =====
function WeekView({
  items,
  currentDate,
  onItemClick,
  onDateClick,
}: {
  items: DisplayItem[];
  currentDate: Date;
  onItemClick: (item: DisplayItem) => void;
  onDateClick?: (date: Date) => void;
}) {
  const weekStart = useMemo(() => getWeekStart(currentDate), [currentDate]);
  
  // 요일 헤더
  const dayLabels = ['월', '화', '수', '목', '금', '토', '일'];
  
  // 날짜 헤더
  const headerDays = useMemo(() => {
    const result: Date[] = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(weekStart);
      d.setDate(d.getDate() + i);
      result.push(d);
    }
    return result;
  }, [weekStart]);
  
  const today = new Date();
  
  return (
    <div className="timeline-week-view">
      {/* 헤더 */}
      <div className="week-header">
        {headerDays.map((day, idx) => {
          const isToday = isSameDay(day, today);
          const dateStr = formatDateStr(day);
          const holidayName = getHolidayName(dateStr);
          return (
            <div key={idx} className={`week-header-cell ${isToday ? 'today' : ''} ${holidayName ? 'holiday' : ''}`}>
              <span className="day-label">{dayLabels[idx]}</span>
              <span className={`day-number ${isToday ? 'today' : ''} ${holidayName ? 'holiday' : ''}`}>{day.getDate()}</span>
              {holidayName && <span className="holiday-name">{holidayName}</span>}
            </div>
          );
        })}
      </div>
      
      {/* 주 행 (All-day 일정) */}
      <WeekRow
        weekStart={weekStart}
        items={items}
        showDayNumbers={false}
        onItemClick={onItemClick}
        onDateClick={onDateClick}
      />
    </div>
  );
}

// ===== Month 뷰 =====
function MonthView({
  items,
  currentDate,
  onItemClick,
  onDateClick,
}: {
  items: DisplayItem[];
  currentDate: Date;
  onItemClick: (item: DisplayItem) => void;
  onDateClick?: (date: Date) => void;
}) {
  // 해당 월의 주들
  const weeks = useMemo(() => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    
    const result: Date[] = [];
    let current = getWeekStart(firstDay);
    
    while (current <= lastDay) {
      result.push(new Date(current));
      current.setDate(current.getDate() + 7);
    }
    
    return result;
  }, [currentDate]);
  
  const currentMonth = currentDate.getMonth();
  
  // 현재 월에 속하는지
  const isCurrentMonth = useCallback((date: Date) => {
    return date.getMonth() === currentMonth;
  }, [currentMonth]);
  
  // 요일 헤더
  const dayLabels = ['월', '화', '수', '목', '금', '토', '일'];
  
  return (
    <div className="timeline-month-view">
      {/* 요일 헤더 */}
      <div className="month-header">
        {dayLabels.map((label, idx) => (
          <div key={idx} className="month-header-cell">{label}</div>
        ))}
      </div>
      
      {/* 주별 행들 */}
      <div className="month-body">
        {weeks.map((weekStart, idx) => (
          <WeekRow
            key={idx}
            weekStart={weekStart}
            items={items}
            showDayNumbers={true}
            isCurrentMonth={isCurrentMonth}
            onItemClick={onItemClick}
            onDateClick={onDateClick}
          />
        ))}
      </div>
    </div>
  );
}

// ===== Year 뷰 (3x4 그리드) =====
function YearView({
  items,
  currentDate,
  onItemClick,
  onMonthClick,
}: {
  items: DisplayItem[];
  currentDate: Date;
  onItemClick: (item: DisplayItem) => void;
  onMonthClick: (date: Date) => void;
}) {
  const year = currentDate.getFullYear();
  
  // 각 월별 아이템 수 계산
  const monthData = useMemo(() => {
    const result: { month: number; date: Date; itemCount: number; items: DisplayItem[] }[] = [];
    
    for (let month = 0; month < 12; month++) {
      const monthStart = new Date(year, month, 1);
      const monthEnd = new Date(year, month + 1, 0);
      
      const monthItems = items.filter(item => {
        if (!item.startAt && !item.endAt) return false;
        const start = item.startAt || item.endAt!;
        const end = item.endAt || item.startAt!;
        return start <= monthEnd && end >= monthStart;
      });
      
      result.push({
        month,
        date: monthStart,
        itemCount: monthItems.length,
        items: monthItems.slice(0, 5), // 최대 5개만 미리보기
      });
    }
    
    return result;
  }, [year, items]);
  
  const monthNames = ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'];
  const today = new Date();
  const currentMonth = today.getMonth();
  const isCurrentYear = today.getFullYear() === year;
  
  return (
    <div className="timeline-year-view">
      <div className="year-grid">
        {monthData.map(({ month, date, itemCount, items: monthItems }) => (
          <div
            key={month}
            className={`month-cell ${isCurrentYear && month === currentMonth ? 'current' : ''}`}
            onClick={() => onMonthClick(date)}
          >
            <div className="month-name">{monthNames[month]}</div>
            
            {/* 미니 캘린더 또는 아이템 미리보기 */}
            <div className="month-preview">
              {monthItems.slice(0, 3).map((item) => (
                <div
                  key={item.id}
                  className="preview-bar"
                  style={{ backgroundColor: item.color }}
                  onClick={(e) => {
                    e.stopPropagation();
                    onItemClick(item);
                  }}
                  title={item.title}
                >
                  {item.title}
                </div>
              ))}
              {itemCount > 3 && (
                <div className="more-count">+{itemCount - 3}개 더</div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ===== 메인 타임라인 컴포넌트 (Projects/Tasks/Todos 공용) =====
interface WorkTimelineBaseProps {
  items: (Project | ProjectTask | ProjectTodo)[];
  scheduleEvents?: ScheduleEvent[];
  type: 'project' | 'task' | 'todo';
  projects?: Project[];
  tasks?: ProjectTask[];
  onItemClick: (item: Project | ProjectTask | ProjectTodo | ScheduleEvent) => void;
  onScheduleEventClick?: (event: ScheduleEvent) => void;
  onAddClick?: (date?: Date) => void;
}

export function ProjectsTimeline({ 
  items, 
  projects, 
  scheduleEvents,
  onItemClick, 
  onScheduleEventClick,
  onAddClick 
}: Omit<WorkTimelineBaseProps, 'type' | 'tasks'> & { items: Project[]; projects?: Project[] }) {
  return (
    <WorkTimelineBase 
      items={items} 
      scheduleEvents={scheduleEvents}
      type="project" 
      projects={projects} 
      onItemClick={onItemClick} 
      onScheduleEventClick={onScheduleEventClick}
      onAddClick={onAddClick} 
    />
  );
}

export function TasksTimeline({ 
  items, 
  projects, 
  scheduleEvents, 
  onItemClick, 
  onScheduleEventClick, 
  onAddClick 
}: Omit<WorkTimelineBaseProps, 'type' | 'tasks'> & { items: ProjectTask[]; projects?: Project[] }) {
  return (
    <WorkTimelineBase 
      items={items} 
      scheduleEvents={scheduleEvents} 
      type="task" 
      projects={projects} 
      onItemClick={onItemClick} 
      onScheduleEventClick={onScheduleEventClick}
      onAddClick={onAddClick} 
    />
  );
}

export function TodosTimeline({ 
  items, 
  tasks, 
  projects, 
  scheduleEvents,
  onItemClick, 
  onScheduleEventClick,
  onAddClick 
}: Omit<WorkTimelineBaseProps, 'type'> & { items: ProjectTodo[]; tasks?: ProjectTask[]; projects?: Project[] }) {
  return (
    <WorkTimelineBase 
      items={items} 
      scheduleEvents={scheduleEvents}
      type="todo" 
      tasks={tasks} 
      projects={projects} 
      onItemClick={onItemClick} 
      onScheduleEventClick={onScheduleEventClick}
      onAddClick={onAddClick} 
    />
  );
}

function WorkTimelineBase({
  items,
  scheduleEvents = [],
  type,
  projects = [],
  tasks = [],
  onItemClick,
  onScheduleEventClick,
  onAddClick,
}: WorkTimelineBaseProps) {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [zoom, setZoom] = useState<ZoomLevel>('month');
  
  // DisplayItem으로 변환
  const displayItems: DisplayItem[] = useMemo(() => {
    const result: DisplayItem[] = [];
    
    // Work 아이템
    items.forEach(item => {
      let color = '#a5b4fc';
      let startAt: Date | null = null;
      let endAt: Date | null = null;
      let title = '';
      
      if (type === 'project') {
        const p = item as Project;
        color = p.color;
        title = p.title;
        startAt = parseDate(p.start_at);
        endAt = parseDate(p.end_at) || parseDate(p.due_at);
      } else if (type === 'task') {
        const t = item as ProjectTask;
        const proj = projects.find(p => p.id === t.projectId);
        color = proj?.color || '#a5b4fc';
        title = t.title;
        startAt = parseDate(t.start_at);
        endAt = parseDate(t.end_at) || parseDate(t.due_at);
      } else {
        const td = item as ProjectTodo;
        const task = tasks.find(t => t.id === td.taskId);
        const proj = task ? projects.find(p => p.id === task.projectId) : null;
        color = proj?.color || '#a5b4fc';
        title = td.content;
        startAt = parseDate(td.start_at);
        endAt = parseDate(td.end_at) || parseDate(td.due_at);
      }
      
      // 시작/끝이 없으면 scheduled에서 제외 (미정 섹션에서 표시)
      if (!startAt && !endAt) return;
      
      // 단일 날짜면 같은 날로 설정
      if (!startAt) startAt = endAt;
      if (!endAt) endAt = startAt;
      
      result.push({
        id: item.id,
        title,
        color,
        startAt,
        endAt,
        isAllDay: true,
        original: item,
        type,
      });
    });
    
    // 일정 이벤트 (모든 타임라인에서 표시)
    scheduleEvents.forEach(event => {
      let startAt = new Date(`${event.date}T${event.start}`);
      let endAt: Date;
      
      if (event.endDate) {
        endAt = new Date(`${event.endDate}T${event.end}`);
      } else {
        endAt = new Date(`${event.date}T${event.end}`);
      }
      
      // 종일 이벤트
      if (event.isAllDay) {
        startAt = new Date(`${event.date}T00:00`);
        if (event.endDate) {
          endAt = new Date(`${event.endDate}T23:59`);
        } else {
          endAt = new Date(`${event.date}T23:59`);
        }
      }
      
      result.push({
        id: event.id,
        title: event.title,
        color: event.color,
        startAt,
        endAt,
        isAllDay: event.isAllDay || false,
        original: event,
        type: 'schedule',
        isScheduleEvent: true,
      });
    });
    
    return result;
  }, [items, scheduleEvents, type, projects, tasks]);

  // 미정 항목 (시작일/종료일/마감일이 모두 없는 항목)
  const unscheduledItems = useMemo(() => {
    return items.filter(item => {
      if (type === 'project') {
        const p = item as Project;
        return !p.start_at && !p.end_at && !p.due_at;
      } else if (type === 'task') {
        const t = item as ProjectTask;
        return !t.start_at && !t.end_at && !t.due_at;
      } else {
        const td = item as ProjectTodo;
        return !td.start_at && !td.end_at && !td.due_at;
      }
    });
  }, [items, type]);
  
  // 네비게이션
  const navigateTimeline = (direction: -1 | 1) => {
    const d = new Date(currentDate);
    if (zoom === 'week') {
      d.setDate(d.getDate() + direction * 7);
    } else if (zoom === 'month') {
      d.setMonth(d.getMonth() + direction);
    } else {
      d.setFullYear(d.getFullYear() + direction);
    }
    setCurrentDate(d);
  };

  // 스와이프 핸들러
  const swipeHandlers = useSwipe({
    onSwipeLeft: () => navigateTimeline(1),
    onSwipeRight: () => navigateTimeline(-1),
  });
  
  const goToToday = () => setCurrentDate(new Date());
  
  // 헤더 텍스트
  const headerText = useMemo(() => {
    if (zoom === 'week') {
      const start = getWeekStart(currentDate);
      const end = new Date(start);
      end.setDate(end.getDate() + 6);
      return `${start.getFullYear()}년 ${start.getMonth() + 1}월 ${start.getDate()}일 - ${end.getMonth() + 1}월 ${end.getDate()}일`;
    } else if (zoom === 'month') {
      return `${currentDate.getFullYear()}년 ${currentDate.getMonth() + 1}월`;
    } else {
      return `${currentDate.getFullYear()}년`;
    }
  }, [currentDate, zoom]);
  
  // 아이템 클릭 핸들러
  const handleItemClick = (displayItem: DisplayItem) => {
    if (displayItem.isScheduleEvent && onScheduleEventClick) {
      onScheduleEventClick(displayItem.original as ScheduleEvent);
    } else {
      onItemClick(displayItem.original as Project | ProjectTask | ProjectTodo);
    }
  };
  
  // 날짜 클릭 핸들러
  const handleDateClick = (date: Date) => {
    onAddClick?.(date);
  };
  
  // 월 클릭 핸들러 (Year 뷰)
  const handleMonthClick = (date: Date) => {
    setCurrentDate(date);
    setZoom('month');
  };
  
  return (
    <div className="work-timeline">
      {/* 컨트롤 바 */}
      <div className="timeline-controls">
        <div className="nav-buttons">
          <button onClick={() => navigateTimeline(-1)}>◀</button>
          <button onClick={goToToday}>오늘</button>
          <button onClick={() => navigateTimeline(1)}>▶</button>
        </div>
        
        <span className="timeline-title">{headerText}</span>
        
        <div className="zoom-buttons">
          <button 
            className={zoom === 'week' ? 'active' : ''} 
            onClick={() => setZoom('week')}
          >
            주
          </button>
          <button 
            className={zoom === 'month' ? 'active' : ''} 
            onClick={() => setZoom('month')}
          >
            월
          </button>
          <button 
            className={zoom === 'year' ? 'active' : ''} 
            onClick={() => setZoom('year')}
          >
            연
          </button>
        </div>
        
        {onAddClick && (
          <button className="add-btn" onClick={() => onAddClick()}>+ 추가</button>
        )}
      </div>
      
      {/* 뷰 렌더링 */}
      <div className="timeline-content" {...swipeHandlers}>
        {zoom === 'week' && (
          <WeekView
            items={displayItems}
            currentDate={currentDate}
            onItemClick={handleItemClick}
            onDateClick={handleDateClick}
          />
        )}
        {zoom === 'month' && (
          <MonthView
            items={displayItems}
            currentDate={currentDate}
            onItemClick={handleItemClick}
            onDateClick={handleDateClick}
          />
        )}
        {zoom === 'year' && (
          <YearView
            items={displayItems}
            currentDate={currentDate}
            onItemClick={handleItemClick}
            onMonthClick={handleMonthClick}
          />
        )}
      </div>

      {/* 미정 섹션 */}
      {unscheduledItems.length > 0 && (
        <div className="unscheduled-section">
          <div className="unscheduled-header">
            <span className="unscheduled-title">📅 미정</span>
            <span className="unscheduled-count">{unscheduledItems.length}</span>
          </div>
          <div className="unscheduled-items">
            {unscheduledItems.map(item => {
              let title = '';
              let color = '#a5b4fc';
              let subtitle = '';
              
              if (type === 'project') {
                const p = item as Project;
                title = p.title;
                color = p.color;
              } else if (type === 'task') {
                const t = item as ProjectTask;
                title = t.title;
                const proj = projects.find(p => p.id === t.projectId);
                color = proj?.color || '#a5b4fc';
                subtitle = proj?.title || '';
              } else {
                const td = item as ProjectTodo;
                title = td.content;
                const task = tasks.find(t => t.id === td.taskId);
                const proj = task ? projects.find(p => p.id === task.projectId) : null;
                color = proj?.color || '#a5b4fc';
                subtitle = task?.title || '';
              }
              
              return (
                <div
                  key={item.id}
                  className="unscheduled-item"
                  onClick={() => onItemClick(item as Project | ProjectTask | ProjectTodo)}
                >
                  <span 
                    className="unscheduled-indicator" 
                    style={{ backgroundColor: color }}
                  />
                  <span className="unscheduled-item-title">{title}</span>
                  {subtitle && <span className="unscheduled-item-subtitle">{subtitle}</span>}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export default WorkTimelineBase;
