// Tasks List 모드 컴포넌트
import React, { useState, useEffect } from 'react';
import type { ProjectTask, Project } from '../../types/work';
import { isReadOnlyItem } from '../../utils/scheduleAdapter';
import './TaskList.css';

interface TaskListProps {
  tasks: ProjectTask[];
  doneTasks: ProjectTask[];
  projects: Project[];
  showCompleted: boolean;
  onAddClick: () => void;
  onSelectTask: (task: ProjectTask) => void;
  onCompleteTask: (taskId: string) => Promise<void>;
  onUndoComplete: (taskId: string) => Promise<void>;
  onReorderTasks: (taskIds: string[]) => Promise<void>;
  onDeleteTask?: (taskId: string) => Promise<void>;
  selectedTaskId?: string | null;
}

export default function TaskList({
  tasks,
  doneTasks,
  projects,
  showCompleted,
  onAddClick,
  onSelectTask,
  onCompleteTask,
  onUndoComplete,
  onReorderTasks,
  onDeleteTask,
  selectedTaskId,
}: TaskListProps) {
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth <= 768);
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // 삭제 핸들러
  const handleDelete = async (e: React.MouseEvent, taskId: string) => {
    e.stopPropagation();
    if (!onDeleteTask) return;
    if (confirm('정말로 이 Task를 삭제하시겠습니까?\n(하위 To do도 함께 삭제됩니다)')) {
      try {
        await onDeleteTask(taskId);
      } catch (error) {
        console.error('Failed to delete task:', error);
      }
    }
  };

  // 완료 토글
  const handleToggleComplete = async (e: React.MouseEvent, task: ProjectTask) => {
    e.stopPropagation();
    try {
      if (task.status === 'DONE') {
        await onUndoComplete(task.id);
      } else {
        await onCompleteTask(task.id);
      }
    } catch (error) {
      console.error('Failed to toggle task completion:', error);
    }
  };

  // 드래그 시작
  const handleDragStart = (e: React.DragEvent, taskId: string) => {
    setDraggedId(taskId);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', taskId);
    const target = e.target as HTMLElement;
    target.style.opacity = '0.5';
  };

  // 드래그 종료
  const handleDragEnd = (e: React.DragEvent) => {
    const target = e.target as HTMLElement;
    target.style.opacity = '1';
    setDraggedId(null);
    setDragOverId(null);
  };

  // 드래그 오버
  const handleDragOver = (e: React.DragEvent, taskId: string) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (taskId !== draggedId) {
      setDragOverId(taskId);
    }
  };

  // 드롭
  const handleDrop = async (e: React.DragEvent, targetId: string) => {
    e.preventDefault();

    if (!draggedId || draggedId === targetId) {
      setDraggedId(null);
      setDragOverId(null);
      return;
    }

    const currentOrder = tasks.map(t => t.id);
    const draggedIndex = currentOrder.indexOf(draggedId);
    const targetIndex = currentOrder.indexOf(targetId);

    if (draggedIndex === -1 || targetIndex === -1) return;

    const newOrder = [...currentOrder];
    newOrder.splice(draggedIndex, 1);
    newOrder.splice(targetIndex, 0, draggedId);

    try {
      await onReorderTasks(newOrder);
    } catch (error) {
      console.error('Failed to reorder tasks:', error);
    }

    setDraggedId(null);
    setDragOverId(null);
  };

  // 프로젝트 색상 가져오기
  const getProjectColor = (projectId: string | null): string => {
    if (!projectId) return '#64748b';
    const project = projects.find(p => p.id === projectId);
    return project?.color || '#64748b';
  };

  // 프로젝트 이름 가져오기
  const getProjectName = (projectId: string | null): string => {
    if (!projectId) return '미분류';
    const project = projects.find(p => p.id === projectId);
    return project?.title || '미분류';
  };

  // 날짜 포맷
  const formatDate = (dateStr: string | null): string => {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ko-KR', { month: 'short', day: 'numeric' });
  };

  return (
    <div className="task-list">
      {/* 새 태스크 추가 버튼 */}
      <button className="add-task-btn-large" onClick={onAddClick}>
        + New Task
      </button>

      {/* 활성 태스크 목록 */}
      <div className="tasks-section">
        {tasks.length === 0 ? (
          <div className="empty-tasks">
            <span className="empty-icon">✅</span>
            <p>태스크가 없습니다</p>
            <p className="empty-hint">위에서 새 태스크를 만들어보세요</p>
          </div>
        ) : (
          <ul className="tasks-items">
            {tasks.map((task) => {
              const isReadOnly = isReadOnlyItem(task.id);
              return (
                <li
                  key={task.id}
                  className={`task-item ${selectedTaskId === task.id ? 'selected' : ''} ${dragOverId === task.id ? 'drag-over' : ''} ${isReadOnly ? 'read-only' : ''}`}
                  draggable={!isReadOnly && !isMobile}
                  onDragStart={(e) => !isReadOnly && !isMobile && handleDragStart(e, task.id)}
                  onDragEnd={!isMobile ? handleDragEnd : undefined}
                  onDragOver={(e) => !isReadOnly && !isMobile && handleDragOver(e, task.id)}
                  onDrop={(e) => !isReadOnly && handleDrop(e, task.id)}
                  onClick={() => !isReadOnly && onSelectTask(task)}
                  onTouchEnd={(e) => {
                    if (isReadOnly) return;
                    if ((e.target as HTMLElement).closest('button')) return;
                    e.preventDefault();
                    onSelectTask(task);
                  }}
                >
                  {!isReadOnly ? (
                    <button
                      className="complete-btn"
                      onClick={(e) => handleToggleComplete(e, task)}
                      title="완료 처리"
                    >
                      ○
                    </button>
                  ) : (
                    <span className="readonly-badge" title="일정관리에서 가져온 항목 (읽기 전용)">📅</span>
                  )}
                  <span
                    className="task-project-indicator"
                    style={{ backgroundColor: isReadOnly ? '#64748b' : getProjectColor(task.projectId) }}
                    title={isReadOnly ? '일정' : getProjectName(task.projectId)}
                  />
                  <div className="task-content">
                    <span className="task-title">{task.title}</span>
                    {/* 소속 프로젝트 이름 */}
                    {!isReadOnly && (
                      <span className="task-project-name">{getProjectName(task.projectId)}</span>
                    )}
                  </div>
                  {/* 마감일 또는 종료일 표시 (오른쪽) */}
                  {(task.due_at || task.end_at) && (
                    <span className="task-date-badge">
                      {task.due_at ? `마감: ${formatDate(task.due_at)}` : `종료: ${formatDate(task.end_at || '')}`}
                    </span>
                  )}
                  {!isReadOnly && <span className="drag-handle">⋮⋮</span>}
                  {!isReadOnly && onDeleteTask && (
                    <button
                      className="delete-btn"
                      onClick={(e) => handleDelete(e, task.id)}
                      title="삭제"
                    >
                      ×
                    </button>
                  )}
                </li>
              );
            })}
          </ul>
        )}
      </div>

      {/* 완료된 태스크 */}
      {showCompleted && doneTasks.length > 0 && (
        <div className="completed-section">
          <div className="section-header">
            <span className="section-title">✓ 완료됨</span>
            <span className="section-count">{doneTasks.length}</span>
          </div>
          <ul className="tasks-items completed">
            {doneTasks.map((task) => (
              <li
                key={task.id}
                className={`task-item completed ${selectedTaskId === task.id ? 'selected' : ''}`}
                onClick={() => onSelectTask(task)}
                onTouchEnd={(e) => {
                  if ((e.target as HTMLElement).closest('button')) return;
                  e.preventDefault();
                  onSelectTask(task);
                }}
              >
                <button
                  className="complete-btn done"
                  onClick={(e) => handleToggleComplete(e, task)}
                  title="완료 취소"
                >
                  ✓
                </button>
                <span
                  className="task-project-indicator"
                  style={{ backgroundColor: getProjectColor(task.projectId), opacity: 0.5 }}
                />
                <div className="task-content">
                  <span className="task-title">{task.title}</span>
                  {task.completed_at && (
                    <span className="task-dates">
                      완료: {new Date(task.completed_at).toLocaleDateString('ko-KR')}
                    </span>
                  )}
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
